DROP TABLE IF EXISTS facilities_staging_2;
CREATE TABLE facilities_staging_2 (LIKE facilities INCLUDING ALL);


SELECT count(*) FROM facilities_staging_2;

UPDATE facilities f SET gps_coordinates = s.gps_coordinates, latitude = s.latitude, longitude = s.longitude FROM facilities_staging_2 s WHERE f.facility_id = s.facility_id AND s.gps_coordinates IS NOT NULL;

SELECT count(*) as updated_count FROM facilities WHERE gps_coordinates IS NOT NULL;